CREATE TYPE "OnboardingType" AS ENUM ('WIFI_BLE','ZIGBEE_GATEWAY','TUYA','GATEWAY');
CREATE TYPE "OnboardingStatus" AS ENUM ('IDLE','PERMISSION_REQUIRED','BLUETOOTH_DISABLED','SCANNING','DEVICE_FOUND','DEVICE_SELECTED','PROVISIONING','WAITING_FOR_NETWORK','REGISTERING','SUCCESS','FAILED','UNSUPPORTED','CANCELLED','EXPIRED');
CREATE TYPE "ProvisioningProvider" AS ENUM ('WEB_BLUETOOTH','GATEWAY','TUYA');
CREATE TYPE "GatewayType" AS ENUM ('ZIGBEE','TUYA','MULTIPROTOCOL');
CREATE TYPE "GatewayConnectionType" AS ENUM ('WIFI','ETHERNET');
CREATE TABLE "Gateway" ("id" UUID NOT NULL,"homeId" UUID NOT NULL,"name" TEXT NOT NULL,"gatewayType" "GatewayType" NOT NULL,"manufacturer" TEXT,"model" TEXT,"externalGatewayId" TEXT,"connectionType" "GatewayConnectionType" NOT NULL,"isOnline" BOOLEAN NOT NULL DEFAULT false,"lastSeenAt" TIMESTAMP(3),"isArchived" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Gateway_pkey" PRIMARY KEY("id"));
CREATE TABLE "DeviceOnboardingSession" ("id" UUID NOT NULL,"homeId" UUID NOT NULL,"roomId" UUID,"initiatedByUserId" UUID NOT NULL,"onboardingType" "OnboardingType" NOT NULL,"protocol" "DeviceProtocol" NOT NULL,"status" "OnboardingStatus" NOT NULL DEFAULT 'IDLE',"discoveredIdentifier" TEXT,"provider" "ProvisioningProvider","expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeviceOnboardingSession_pkey" PRIMARY KEY("id"));
CREATE TABLE "DeviceIntegrationIdentity" ("id" UUID NOT NULL,"deviceId" UUID NOT NULL,"provider" "ProvisioningProvider" NOT NULL,"externalId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeviceIntegrationIdentity_pkey" PRIMARY KEY("id"));
CREATE INDEX "Gateway_homeId_isArchived_idx" ON "Gateway"("homeId","isArchived");
CREATE INDEX "DeviceOnboardingSession_homeId_status_idx" ON "DeviceOnboardingSession"("homeId","status"); CREATE INDEX "DeviceOnboardingSession_expiresAt_idx" ON "DeviceOnboardingSession"("expiresAt");
CREATE UNIQUE INDEX "DeviceIntegrationIdentity_provider_externalId_key" ON "DeviceIntegrationIdentity"("provider","externalId"); CREATE INDEX "DeviceIntegrationIdentity_deviceId_idx" ON "DeviceIntegrationIdentity"("deviceId");
ALTER TABLE "Gateway" ADD CONSTRAINT "Gateway_homeId_fkey" FOREIGN KEY("homeId") REFERENCES "Home"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DeviceOnboardingSession" ADD CONSTRAINT "DeviceOnboardingSession_homeId_fkey" FOREIGN KEY("homeId") REFERENCES "Home"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DeviceOnboardingSession" ADD CONSTRAINT "DeviceOnboardingSession_roomId_fkey" FOREIGN KEY("roomId") REFERENCES "Room"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "DeviceOnboardingSession" ADD CONSTRAINT "DeviceOnboardingSession_initiatedByUserId_fkey" FOREIGN KEY("initiatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DeviceIntegrationIdentity" ADD CONSTRAINT "DeviceIntegrationIdentity_deviceId_fkey" FOREIGN KEY("deviceId") REFERENCES "Device"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE FUNCTION enforce_onboarding_room_home() RETURNS trigger AS $$ BEGIN IF NEW."roomId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "Room" WHERE "id"=NEW."roomId" AND "homeId"=NEW."homeId") THEN RAISE EXCEPTION 'Onboarding Room must belong to Home' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "Onboarding_room_home_guard" BEFORE INSERT OR UPDATE OF "homeId","roomId" ON "DeviceOnboardingSession" FOR EACH ROW EXECUTE FUNCTION enforce_onboarding_room_home();
CREATE FUNCTION guard_onboarding_terminal_state() RETURNS trigger AS $$ BEGIN IF OLD."status" IN ('SUCCESS','CANCELLED','EXPIRED') AND OLD."status"<>NEW."status" THEN RAISE EXCEPTION 'terminal onboarding status cannot transition' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "Onboarding_terminal_guard" BEFORE UPDATE OF "status" ON "DeviceOnboardingSession" FOR EACH ROW EXECUTE FUNCTION guard_onboarding_terminal_state();
